LESSON_DB.business.m3 = {
  0: {emoji:"🧠", subtitle:"Grade 10–12 · Creative thinking and problem solving",
    illusText:"Define the problem → generate options → choose → implement → evaluate.",
    hook:{title:"The jam-jar lamp", body:"During load shedding, a group of learners made lamps from solar garden lights and old jam jars — then sold them. That's <strong>creative thinking</strong> applied to a real problem. Businesses rely on it every day, from cutting costs to inventing new products."},
    intro:"<strong>Creative thinking</strong> means generating new ideas or new ways of doing things. Benefits for a business: a competitive advantage, new products, better solutions, motivated staff. Ways to encourage it: a supportive culture, rewards for ideas, suggestion boxes, brainstorming sessions, time and resources to experiment. <strong>Problem-solving steps</strong>: identify and define the problem; gather information; generate alternative solutions; evaluate them and choose the best; implement it; evaluate the result. <strong>Problem-solving techniques</strong> (Grade 11–12): <strong>brainstorming</strong> (many ideas, no criticism), <strong>nominal group technique</strong> (individuals write ideas, then rank them as a group), <strong>Delphi technique</strong> (experts answer questionnaires separately until they agree), <strong>force-field analysis</strong> (weigh forces for and against a change), <strong>SCAMPER</strong> (substitute, combine, adapt, modify, put to other use, eliminate, reverse), the <strong>empty chair technique</strong> and <strong>forced combinations</strong>. Decision-making vs problem-solving: decisions can be made by one person; problem-solving is often a team process.",
    concepts:[
      {t:"green", title:"💡 Creativity", body:"New ideas give a competitive advantage."},
      {t:"teal", title:"🔁 Steps", body:"Define → options → choose → implement → evaluate."},
      {t:"gold", title:"🛠️ Techniques", body:"Brainstorming, nominal group, Delphi, force-field, SCAMPER."},
    ],
    examples:[
      {title:"Technique", body:"Experts in different cities answer questionnaires until they agree.", answer:"The <strong>Delphi technique</strong>."},
      {title:"Technique", body:"Staff list forces for and against moving to a four-day week.", answer:"<strong>Force-field analysis</strong>."},
      {title:"Step", body:"After a new delivery system starts, the manager checks if complaints dropped.", answer:"<strong>Evaluating</strong> the solution."},
    ],
    mistakes:["Jumping to a solution before defining the problem.","Criticising ideas during brainstorming.","Confusing Delphi (separate experts) with nominal group (one room)."],
    callout:{title:"SCAMPER", body:"Substitute, Combine, Adapt, Modify, Put to other use, Eliminate, Reverse."},
    activity:"Use SCAMPER on a school lunchbox. Write one idea for each letter.",
    activityAnswer:"Examples: Substitute plastic with bamboo; Combine with a water bottle; Adapt for keeping food cold; Modify with compartments; Put to other use as a pencil case; Eliminate the lid with a fold-over flap; Reverse — a lunch bag that becomes a placemat.",
    examTip:"When a case study describes a technique, name it and quote the words that show it.",
    keyterms:[{w:"Brainstorming",d:"Generating many ideas without criticism"},{w:"Delphi technique",d:"Experts answer separately until consensus"},{w:"Force-field analysis",d:"Weighing forces for and against a change"}],
    quiz:[
      {q:"The first problem-solving step is to:",opts:["Implement","Define the problem","Evaluate","Choose a solution"],a:1,et:"Know what you're solving."},
      {q:"In brainstorming, ideas are:",opts:["Criticised immediately","Not criticised","Voted on first","Written by experts only"],a:1,et:"Quantity first."},
      {q:"Weighing forces for and against change is:",opts:["Delphi","Force-field analysis","SCAMPER","Nominal group"],a:1,et:"Kurt Lewin's model."},
    ],
    conclusion:"Creative thinking and structured problem-solving techniques help businesses find better solutions and stay competitive."},

  1: {emoji:"🌪️", subtitle:"Grade 11 · Stress, crisis and change management",
    illusText:"Stress → coping strategies · crisis → crisis plan · change → manage resistance.",
    hook:{title:"When the warehouse flooded", body:"In the 2022 KwaZulu-Natal floods, many businesses lost stock, buildings and records overnight. Those that recovered fastest had a <strong>crisis plan</strong>, backups and insurance. Their staff were also under huge <strong>stress</strong> — and every business had to manage <strong>change</strong>."},
    intro:"<strong>Stress</strong>: a physical and emotional response to pressure. Causes at work: heavy workload, job insecurity, poor relationships, change, long hours. Effects: absenteeism, poor performance, illness. Managing stress: time management, exercise, a healthy lifestyle, talking to someone, employee wellness programmes. <strong>Crisis</strong>: an unexpected event that threatens the business (fire, flood, cyberattack, death of a key person, fraud, pandemic). <strong>Crisis management</strong>: have a crisis plan, a crisis team, communicate quickly and honestly, back up data, insure assets, review afterwards. <strong>Change</strong>: new technology, new management, restructuring, mergers. People resist change because of fear of the unknown, job loss, lack of information or loss of status. Managing change: communicate early, involve staff, provide training, support and reward adaptation, implement gradually where possible.",
    concepts:[
      {t:"green", title:"😓 Stress", body:"Recognise causes, reduce workload, support wellness."},
      {t:"teal", title:"🚨 Crisis", body:"Plan, team, communication, backups, insurance."},
      {t:"gold", title:"🔄 Change", body:"Communicate, involve, train and support."},
    ],
    examples:[
      {title:"Crisis", body:"A hacker locks the company's computers.", answer:"A <strong>crisis</strong> — use backups, inform customers, involve IT experts, and report it."},
      {title:"Resistance", body:"Why might staff resist new software?", answer:"<strong>Fear</strong> of not coping, job loss, or lack of training."},
      {title:"Stress", body:"Give one way a business can reduce staff stress.", answer:"An <strong>employee wellness programme</strong> or fair workload planning."},
    ],
    mistakes:["Treating all change as a crisis.","Ignoring the human side of change.","Saying a crisis plan is only needed after a crisis."],
    callout:{title:"Plan before", body:"The best time to make a crisis plan is when there's no crisis."},
    activity:"Write a one-page crisis plan for your school for one of these: fire, flood or a cyberattack on the school's records.",
    activityAnswer:"Answers vary. A good plan includes: who's on the crisis team, how people are alerted and evacuated, communication with parents, backup of records, insurance details, and a review after the event.",
    examTip:"For change questions, explain both why people resist and how management should respond.",
    keyterms:[{w:"Crisis",d:"Unexpected event threatening the business"},{w:"Resistance to change",d:"Opposition to new ways of working"},{w:"Wellness programme",d:"Support for employees' physical and mental health"}],
    quiz:[
      {q:"Which is a crisis?",opts:["A new logo","A factory fire","A staff party","A price change"],a:1,et:"Unexpected and threatening."},
      {q:"A common reason for resisting change is:",opts:["Too much information","Fear of the unknown","High salaries","Good training"],a:1,et:"Communicate early."},
      {q:"Backing up data helps with:",opts:["Crisis management","Marketing","Recruitment","Pricing"],a:0,et:"Fast recovery."},
    ],
    conclusion:"Manage stress with support, crises with planning and change with communication — people are at the centre of all three."},

  2: {emoji:"👥", subtitle:"Grade 10–12 · Self-management, teams and conflict",
    illusText:"Team stages: forming · storming · norming · performing · adjourning.",
    hook:{title:"The Springboks didn't win by accident", body:"A world-class rugby team isn't just talented individuals — it's a team that has learnt to trust each other, handle conflict and pull in one direction. Businesses work the same way: <strong>teams</strong> that manage themselves well and resolve <strong>conflict</strong> perform better."},
    intro:"<strong>Self-management</strong> (Grade 10): setting goals, managing time, being accountable, personal SWOT. <strong>Teams</strong>: a group working towards a common goal. Characteristics of successful teams: shared goals, clear roles, trust, open communication, mutual respect, good leadership, and members who complement each other. <strong>Team stages</strong> (Tuckman): <strong>forming</strong> (polite, unsure), <strong>storming</strong> (disagreement and conflict), <strong>norming</strong> (rules and roles agreed), <strong>performing</strong> (working effectively), <strong>adjourning</strong> (the task ends). <strong>Team dynamics theories</strong> (Grade 11): <strong>Belbin's team roles</strong> (e.g. coordinator, shaper, implementer, completer-finisher) and the <strong>Myers–Briggs</strong> personality types. <strong>Conflict</strong>: causes — different goals, poor communication, personality clashes, unfair treatment, limited resources. Handling conflict: identify the cause, meet the parties, listen to both sides, brainstorm solutions, agree on a solution, follow up. Grievance procedures and mediation may be needed.",
    concepts:[
      {t:"green", title:"📈 Team stages", body:"Forming, storming, norming, performing, adjourning."},
      {t:"teal", title:"🎭 Roles", body:"Belbin: different people contribute different strengths."},
      {t:"gold", title:"🕊️ Conflict", body:"Find the cause, listen, agree, follow up."},
    ],
    examples:[
      {title:"Stage", body:"A new project team argues about who leads.", answer:"<strong>Storming</strong>."},
      {title:"Stage", body:"The team now has clear rules and roles.", answer:"<strong>Norming</strong>."},
      {title:"Conflict", body:"Two staff clash over a shared deadline.", answer:"Meet both, <strong>listen to each side</strong>, find the cause, agree on a solution and follow up."},
    ],
    mistakes:["Thinking conflict is always bad (it can lead to better ideas).","Mixing up norming and performing.","Taking sides when resolving conflict."],
    callout:{title:"Healthy conflict", body:"Disagreement about ideas, handled respectfully, often produces better decisions."},
    activity:"Think of a group project you've done. Which team stages did you go through? What would you do differently?",
    activityAnswer:"Answers vary. A good reflection names each stage with an example (e.g. storming when deciding who would present) and suggests an improvement (e.g. agreeing on roles at the start).",
    examTip:"Scenario questions often describe a team stage — quote the evidence from the case study.",
    keyterms:[{w:"Storming",d:"Team stage marked by conflict"},{w:"Belbin roles",d:"Model of the roles people play in teams"},{w:"Mediation",d:"A neutral person helps parties resolve conflict"}],
    quiz:[
      {q:"The stage when a team works most effectively is:",opts:["Forming","Storming","Norming","Performing"],a:3,et:"Roles are clear and trust is high."},
      {q:"A cause of workplace conflict is:",opts:["Clear goals","Poor communication","Good leadership","Fair treatment"],a:1,et:"Misunderstandings grow."},
      {q:"Belbin's theory is about:",opts:["Marketing","Team roles","Taxation","Pricing"],a:1,et:"Nine team roles."},
    ],
    conclusion:"Good self-management, an understanding of team stages and fair conflict resolution turn groups into high-performing teams."},

  3: {emoji:"🧭", subtitle:"Grade 11–12 · Professionalism and ethics",
    illusText:"Professional · ethical · legal — and why they're not always the same thing.",
    hook:{title:"State capture and the cost of corruption", body:"The Zondo Commission found that billions of rands were lost to corruption at state-owned companies. Some actions were illegal; others were legal but clearly unethical. <strong>Professionalism and ethics</strong> are what keep businesses — and countries — trustworthy."},
    intro:"<strong>Professionalism</strong>: behaving in a competent, reliable and respectful way at work (punctuality, dress, confidentiality, quality work). <strong>Ethics</strong>: knowing and doing what is morally right. <strong>Legal</strong> means allowed by law — but something can be legal yet unethical (e.g. paying the minimum wage while executives earn millions). <strong>Unethical and unprofessional practices</strong>: corruption and bribery, tax evasion, unfair advertising, pricing of goods in rural areas (charging poor customers more), sexual harassment, unauthorised use of funds, abuse of work time, discrimination, exploiting workers. <strong>Promoting ethics</strong>: a code of ethics and code of conduct, training, whistle-blowing channels (the Protected Disclosures Act protects whistle-blowers), leading by example, disciplinary action, and good <strong>corporate governance</strong> (King IV Report: transparency, accountability, responsibility, fairness).",
    concepts:[
      {t:"green", title:"👔 Professional", body:"Competent, reliable, respectful behaviour."},
      {t:"teal", title:"⚖️ Ethical vs legal", body:"Legal isn't always ethical."},
      {t:"gold", title:"🏛️ Governance", body:"King IV: transparency, accountability, fairness."},
    ],
    examples:[
      {title:"Classify", body:"A manager gives a tender to a friend's company for a kickback.", answer:"<strong>Illegal and unethical</strong> — corruption."},
      {title:"Classify", body:"A shop in a remote village charges far more than in town because there's no competitor.", answer:"Legal but <strong>unethical</strong> pricing."},
      {title:"Promote", body:"How can a business encourage ethics?", answer:"A <strong>code of ethics</strong>, training, and a safe <strong>whistle-blowing</strong> line."},
    ],
    mistakes:["Treating “legal” and “ethical” as the same.","Listing unethical practices without suggesting solutions.","Forgetting corporate governance."],
    callout:{title:"King IV principles", body:"Integrity, competence, responsibility, accountability, fairness and transparency."},
    activity:"Write a five-point code of conduct for your class or a school club.",
    activityAnswer:"Answers vary. Good codes are specific and measurable, e.g. arrive on time, respect others' opinions, no plagiarism, keep shared resources tidy, report problems to the class representative.",
    examTip:"Distinguish clearly between professional, ethical and legal behaviour in your answers.",
    keyterms:[{w:"Ethics",d:"Moral principles of right and wrong"},{w:"Corporate governance",d:"The system by which a company is directed and controlled"},{w:"Whistle-blower",d:"Person who reports wrongdoing"}],
    quiz:[
      {q:"Which law protects whistle-blowers?",opts:["Protected Disclosures Act","Companies Act","Tax Act","Labour Relations Act"],a:0,et:"Reports in good faith are protected."},
      {q:"An action can be legal but:",opts:["Always ethical","Unethical","Criminal","Unprofessional only"],a:1,et:"Ethics goes beyond law."},
      {q:"The King IV Report deals with:",opts:["Marketing","Corporate governance","Taxation","Recruitment"],a:1,et:"Good company leadership."},
    ],
    conclusion:"Professional, ethical behaviour and strong governance build trust — and legal is the minimum, not the goal."},

  4: {emoji:"🏅", subtitle:"Grade 12 · Quality of performance (TQM)",
    illusText:"Quality control · quality assurance · total quality management · PDCA.",
    hook:{title:"Why one bad review hurts", body:"One viral video of a dirty restaurant kitchen can wipe out years of reputation. Customers today share everything online. That's why businesses invest in <strong>quality</strong> — not as an inspection at the end, but as a culture across every function."},
    intro:"<strong>Quality</strong>: the ability of a product or service to meet customers' needs. <strong>Quality control</strong>: checking finished products for defects. <strong>Quality assurance</strong>: checks during the process to prevent defects. <strong>Quality management</strong>: the systems used to ensure quality. <strong>TQM (total quality management)</strong>: everyone in the business is responsible for quality, always. Elements of TQM: continuous skills development, total client satisfaction, adequate financing and capacity, monitoring and evaluation of quality processes, and continuous improvement. <strong>PDCA cycle</strong> (Deming): plan, do, check, act. Quality in each business function, e.g. HR (recruit skilled staff), marketing (honest advertising, after-sales service), production (efficient processes), purchasing (reliable suppliers). Benefits: customer loyalty, lower costs (less waste), good reputation, competitive advantage. Impact of poor quality: returns, complaints, lost customers. Quality circles: small groups of staff who meet to solve quality problems.",
    concepts:[
      {t:"green", title:"🔍 Control vs assurance", body:"Check at the end vs prevent during the process."},
      {t:"teal", title:"🌐 TQM", body:"Quality is everyone's responsibility, always."},
      {t:"gold", title:"🔄 PDCA", body:"Plan, do, check, act — continuous improvement."},
    ],
    examples:[
      {title:"Classify", body:"Inspectors test every phone before packaging.", answer:"<strong>Quality control</strong>."},
      {title:"TQM element", body:"Staff get regular training on new machines.", answer:"<strong>Continuous skills development</strong>."},
      {title:"Function", body:"How can the purchasing function improve quality?", answer:"Buy from <strong>reliable suppliers</strong> who deliver quality materials on time."},
    ],
    mistakes:["Mixing up quality control and quality assurance.","Thinking TQM is only the production department's job.","Forgetting the customer in quality definitions."],
    callout:{title:"PDCA", body:"Plan a change, Do it on a small scale, Check results, Act to adopt or adjust."},
    activity:"Apply the PDCA cycle to improving the queue at your school tuck shop.",
    activityAnswer:"Plan: pre-packed snack bags and a separate payment line. Do: try it for one week. Check: time the queue and ask learners. Act: keep what works, adjust what doesn't, and repeat.",
    examTip:"When asked about quality in a function, name the function and give a specific action.",
    keyterms:[{w:"TQM",d:"Total quality management"},{w:"Quality assurance",d:"Preventing defects during production"},{w:"Quality circle",d:"Staff group that solves quality problems"}],
    quiz:[
      {q:"Checking finished goods is:",opts:["Quality assurance","Quality control","TQM","PDCA"],a:1,et:"At the end."},
      {q:"In TQM, quality is the responsibility of:",opts:["Inspectors only","Managers only","Everyone","Customers"],a:2,et:"Total."},
      {q:"PDCA stands for:",opts:["Price, demand, cost, action","Plan, do, check, act","Product, distribution, cost, area","Prepare, deliver, control, assess"],a:1,et:"Deming cycle."},
    ],
    conclusion:"Quality is built in, not inspected in — TQM makes it everyone's job and PDCA keeps improving it."},

  5: {emoji:"⚖️", subtitle:"Grade 11–12 · Business legislation",
    illusText:"LRA · BCEA · EEA · SDA · CPA · NCA · BBBEE · COIDA.",
    hook:{title:"Why your payslip shows UIF", body:"If you work part-time at a shop, your payslip probably shows a UIF deduction, limits on your hours and paid leave. Those aren't the boss's favours — they're required by law. South African <strong>business legislation</strong> protects workers, consumers and fair competition."},
    intro:"<strong>Labour Relations Act (LRA)</strong>: the right to join trade unions, collective bargaining, the right to strike, the CCMA to resolve disputes, protection against unfair dismissal. <strong>Basic Conditions of Employment Act (BCEA)</strong>: maximum 45 ordinary hours a week, overtime limits and pay, leave (annual, sick, family responsibility, maternity), employment contracts, and the ban on child labour (under 15). <strong>Employment Equity Act (EEA)</strong>: prohibits unfair discrimination and requires affirmative action plans for designated groups. <strong>Skills Development Act (SDA)</strong>: SETAs, learnerships and the skills development levy (1% of payroll). <strong>BBBEE Act</strong>: promotes black economic participation through ownership, management control, skills development, enterprise and supplier development, and socio-economic development. <strong>Consumer Protection Act (CPA)</strong>: rights to fair pricing, disclosure, safe goods, returns. <strong>National Credit Act (NCA)</strong>: prevents reckless lending. <strong>COIDA</strong>: compensation for injuries at work. <strong>UIF</strong>: unemployment insurance. Businesses that don't comply face fines, legal action and reputational damage.",
    concepts:[
      {t:"green", title:"👷 Workers", body:"LRA, BCEA, EEA, SDA, COIDA, UIF."},
      {t:"teal", title:"🛒 Consumers", body:"CPA and NCA."},
      {t:"gold", title:"📈 Transformation", body:"BBBEE and employment equity."},
    ],
    examples:[
      {title:"Act", body:"A worker is fired without a fair hearing.", answer:"The <strong>LRA</strong> — they can take the case to the <strong>CCMA</strong>."},
      {title:"Act", body:"A shop refuses to replace a faulty kettle within 6 months.", answer:"The <strong>Consumer Protection Act</strong>."},
      {title:"Act", body:"A company pays a levy to fund learnerships.", answer:"The <strong>Skills Development Act</strong>."},
    ],
    mistakes:["Mixing up the LRA (relationships, unions, disputes) and the BCEA (working conditions).","Forgetting that the CPA protects consumers, not employers.","Listing an Act without explaining its impact on business."],
    callout:{title:"Impact questions", body:"Give positive and negative impacts on business, e.g. the BCEA protects workers but increases costs."},
    activity:"Look at a real payslip (yours or a family member's, with permission). Identify each deduction and the law it comes from.",
    activityAnswer:"Typical deductions: PAYE (Income Tax Act), UIF (Unemployment Insurance Act), pension or medical aid (contractual). The BCEA governs hours, overtime and leave shown on the payslip.",
    examTip:"For “discuss the impact” questions, give both positive and negative points for the business.",
    keyterms:[{w:"CCMA",d:"Commission for Conciliation, Mediation and Arbitration"},{w:"SETA",d:"Sector Education and Training Authority"},{w:"Designated groups",d:"Black people, women and people with disabilities (EEA)"}],
    quiz:[
      {q:"Maximum ordinary working hours per week under the BCEA:",opts:["40","45","50","60"],a:1,et:"Plus limited overtime."},
      {q:"Disputes about unfair dismissal go to the:",opts:["SARS","CCMA","SETA","NCR"],a:1,et:"Under the LRA."},
      {q:"Reckless lending is prevented by the:",opts:["CPA","NCA","EEA","SDA"],a:1,et:"National Credit Act."},
    ],
    conclusion:"South Africa's business laws protect workers, consumers and fair competition — and good businesses comply fully."},

  6: {emoji:"📈", subtitle:"Grade 12 · Investment: securities",
    illusText:"Shares · unit trusts · bonds · RSA Retail Savings Bonds · the JSE.",
    hook:{title:"Why your grandmother's stokvel became a unit trust", body:"Stokvels pool money so members can save together. Many now invest part of their savings in <strong>unit trusts</strong> or the <strong>JSE</strong> to grow their money faster than inflation. Choosing where to invest means balancing <strong>risk</strong> and <strong>return</strong>."},
    intro:"<strong>Investment</strong>: putting money into assets to earn a return. Factors to consider: <strong>return</strong> on investment, <strong>risk</strong>, <strong>liquidity</strong> (how quickly you can get the money back), <strong>investment period</strong>, <strong>inflation</strong>, <strong>tax</strong> and <strong>fees</strong>. Types: <strong>fixed deposits</strong> (low risk, fixed interest), <strong>RSA Retail Savings Bonds</strong> (government-backed), <strong>unit trusts</strong> (pooled funds managed by professionals — diversified), <strong>shares</strong> (part-ownership of a listed company; earn dividends and capital growth; higher risk), <strong>bonds</strong> (loans to companies or government). <strong>Ordinary shares</strong>: voting rights, dividends depend on profit. <strong>Preference shares</strong>: fixed dividend paid first, usually no voting rights. <strong>The JSE</strong>: the Johannesburg Stock Exchange where shares are traded; functions include raising capital for companies and a market for investors. <strong>Simple interest</strong>: I = P × i × n. <strong>Compound interest</strong>: A = P(1 + i)ⁿ. A tax-free savings account lets you save up to R36 000 a year without tax on the returns.",
    concepts:[
      {t:"green", title:"⚖️ Risk vs return", body:"Higher potential return usually means higher risk."},
      {t:"teal", title:"💼 Options", body:"Fixed deposits, bonds, unit trusts, shares."},
      {t:"gold", title:"🏦 The JSE", body:"Where listed shares are bought and sold."},
    ],
    examples:[
      {title:"Interest", body:"R10 000 at 8% compound interest for 3 years.", answer:"A = 10 000 × 1.08³ = <strong>R12 597.12</strong>."},
      {title:"Shares", body:"Which shareholders are paid dividends first?", answer:"<strong>Preference shareholders</strong>."},
      {title:"Choice", body:"A pensioner wants low risk and steady income.", answer:"<strong>RSA Retail Savings Bonds</strong> or a <strong>fixed deposit</strong>."},
    ],
    formula:"Simple interest: I = P × i × n · Compound: A = P(1 + i)ⁿ",
    mistakes:["Saying shares guarantee a return.","Confusing ordinary and preference shares.","Ignoring inflation when judging returns."],
    callout:{title:"Diversify", body:"Don't put all your eggs in one basket — spread investments to reduce risk."},
    activity:"Compare R5 000 invested for 5 years at 7% simple interest and 7% compound interest.",
    activityAnswer:"Simple: I = 5 000 × 0.07 × 5 = R1 750 → R6 750. Compound: 5 000 × 1.07⁵ ≈ R7 012.76. Compound earns about R262.76 more.",
    examTip:"Show your formula and substitution in interest calculations — method marks count.",
    keyterms:[{w:"Dividend",d:"Share of profit paid to shareholders"},{w:"Liquidity",d:"How easily an investment turns into cash"},{w:"Unit trust",d:"Pooled investment managed by professionals"}],
    quiz:[
      {q:"Which usually has the highest risk?",opts:["Fixed deposit","Retail savings bond","Shares","Savings account"],a:2,et:"Prices can fall."},
      {q:"Preference shareholders usually:",opts:["Have voting rights","Get a fixed dividend first","Own the company alone","Pay no tax"],a:1,et:"Paid before ordinary shareholders."},
      {q:"JSE stands for:",opts:["Joint Savings Exchange","Johannesburg Stock Exchange","Junior Securities Engine","Joburg Shares Estate"],a:1,et:"Africa's largest stock exchange."},
    ],
    conclusion:"Investing means weighing risk, return and liquidity — from safe bonds to riskier shares on the JSE."},

  7: {emoji:"🛡️", subtitle:"Grade 12 · Investment: insurance",
    illusText:"Insurance vs assurance · premiums · excess · average clause · compulsory insurance.",
    hook:{title:"The shop that burnt down", body:"After the July 2021 unrest, many shop owners lost everything. Those with insurance — including SASRIA cover for riots — could rebuild; many without it never reopened. <strong>Insurance</strong> transfers risk from a business to an insurer for a monthly premium."},
    intro:"<strong>Insurance</strong>: protection against loss from events that <strong>may</strong> happen (fire, theft, accident). <strong>Assurance</strong>: cover for events that <strong>will</strong> happen (death, retirement) — e.g. life assurance. Key terms: <strong>premium</strong> (regular payment), <strong>insured</strong> (person covered), <strong>insurer</strong> (company), <strong>excess</strong> (amount the insured pays first on a claim), <strong>under-insurance</strong> and the <strong>average clause</strong>: if property is under-insured, the claim is reduced in proportion. Formula: amount paid = (amount insured ÷ value of property) × loss. Insurable risks: theft, fire, accidents. Non-insurable risks: business losses from poor management, changes in fashion, competition. <strong>Compulsory insurance</strong> in SA: <strong>UIF</strong>, <strong>COIDA</strong> (injury on duty) and the <strong>Road Accident Fund</strong> (via the fuel levy). <strong>SASRIA</strong> covers riots, strikes and political unrest. Advantages of insurance: protects against loss, peace of mind, business continuity, may be required by lenders.",
    concepts:[
      {t:"green", title:"🛡️ Insurance vs assurance", body:"Might happen vs will happen."},
      {t:"teal", title:"🧮 Average clause", body:"Under-insured? You get a proportional pay-out."},
      {t:"gold", title:"📜 Compulsory", body:"UIF, COIDA and the Road Accident Fund."},
    ],
    examples:[
      {title:"Average clause", body:"Stock worth R200 000 is insured for R150 000. Fire damage: R80 000.", answer:"(150 000 ÷ 200 000) × 80 000 = <strong>R60 000</strong> paid out."},
      {title:"Classify", body:"A policy that pays out when you retire.", answer:"<strong>Assurance</strong> (the event is certain)."},
      {title:"Risk", body:"Can a business insure against losing customers to a competitor?", answer:"No — it's a <strong>non-insurable</strong> business risk."},
    ],
    formula:"Average clause: amount paid = (amount insured ÷ value of property) × damage",
    mistakes:["Mixing up insurance and assurance.","Forgetting the average clause when property is under-insured.","Saying all risks can be insured."],
    callout:{title:"Excess", body:"A higher excess usually means a lower premium — but you pay more when you claim."},
    activity:"A spaza's equipment is worth R50 000 and insured for R40 000. A burglary causes R20 000 damage. Calculate the pay-out.",
    activityAnswer:"(40 000 ÷ 50 000) × 20 000 = R16 000. The owner carries the remaining R4 000 (plus any excess).",
    examTip:"Write the average clause formula, substitute, and show the final amount in rands.",
    keyterms:[{w:"Premium",d:"Regular payment for insurance cover"},{w:"Excess",d:"Part of a claim the insured pays"},{w:"Average clause",d:"Reduces claims when property is under-insured"}],
    quiz:[
      {q:"Life cover is an example of:",opts:["Insurance","Assurance","Excess","SASRIA"],a:1,et:"Death is certain."},
      {q:"Which is compulsory in SA?",opts:["Car insurance","UIF","Life assurance","Household cover"],a:1,et:"Along with COIDA and RAF."},
      {q:"SASRIA covers:",opts:["Old age","Riots and unrest","Normal theft","Illness"],a:1,et:"Special risks."},
    ],
    conclusion:"Insurance shares risk, assurance plans for certainties, and the average clause punishes under-insurance — every business needs the right cover."},
};

