LESSON_DB.business.m0[2].svg = "<svg viewBox=\"0 0 400 220\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"400\" height=\"220\" fill=\"#0d1024\"/><text x=\"16.0\" y=\"24.0\" fill=\"#00C2D4\" font-size=\"12\" text-anchor=\"start\" font-weight=\"700\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">PRIVATE COMPANY (PTY) LTD</text><rect x=\"60.0\" y=\"55.0\" width=\"120.0\" height=\"90.0\" rx=\"8\" fill=\"rgba(0,214,143,.06)\" stroke=\"#00D68F\" stroke-width=\"2\" opacity=\"1\"/><text x=\"120.0\" y=\"85.0\" fill=\"#00D68F\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"800\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">COMPANY</text><text x=\"120.0\" y=\"105.0\" fill=\"#E2E8F0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">separate person</text><text x=\"120.0\" y=\"122.0\" fill=\"#E2E8F0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">owns · owes · sues</text><rect x=\"220.0\" y=\"55.0\" width=\"120.0\" height=\"90.0\" rx=\"8\" fill=\"rgba(0,194,212,.06)\" stroke=\"#00C2D4\" stroke-width=\"2\" opacity=\"1\"/><text x=\"280.0\" y=\"85.0\" fill=\"#00C2D4\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"800\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">OWNER</text><text x=\"280.0\" y=\"105.0\" fill=\"#E2E8F0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">risks only her</text><text x=\"280.0\" y=\"122.0\" fill=\"#E2E8F0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">investment</text><line x1=\"180.0\" y1=\"100.0\" x2=\"220.0\" y2=\"100.0\" stroke=\"#FF6B35\" stroke-width=\"3\" stroke-dasharray=\"4 4\" stroke-linecap=\"round\"/><text x=\"200.0\" y=\"92.0\" fill=\"#E2E8F0\" font-size=\"14\" text-anchor=\"middle\" font-weight=\"600\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">🛡️</text><text x=\"200.0\" y=\"185.0\" fill=\"#FFB800\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"800\" font-family=\"Plus Jakarta Sans,Arial,sans-serif\">CIPC · Companies Act 71 of 2008 · tax 27%</text></svg>";
